function summarySettings(site, spreadsheet, tab, channel, limit) {
  if (
    typeof site !== "string" ||
    !/^https:\/\/(?:(?:[a-z0-9-]+\.)+[a-z][a-z0-9-]*|(?:\d{1,3}\.){3}\d{1,3})(?::\d{1,5})?(?:\/[A-Za-z0-9_-]+)*\/?$/i.test(
      site,
    ) ||
    site === "https://example.invalid" ||
    /\/wp-json(?:\/|$)/.test(site)
  ) {
    throw new Error("Set your WordPress HTTPS site URL, without /wp-json.");
  }
  if (
    !/^[A-Za-z0-9_-]{20,120}$/.test(spreadsheet) ||
    spreadsheet === "YOUR_SPREADSHEET_ID" ||
    !/^[A-Za-z0-9_ -]{1,80}$/.test(tab) ||
    !/^[CG][A-Z0-9]{8,}$/.test(channel)
  ) {
    throw new Error("Set the spreadsheet ID, worksheet tab and Slack channel ID.");
  }
  if (!Number.isInteger(limit) || limit < 1 || limit > 10)
    throw new Error("Choose a post limit between one and ten.");
  const root = site.replace(/\/$/, "");
  return {
    site: root,
    origin: /^https:\/\/[^/]+/.exec(root)[0],
    spreadsheet,
    tab,
    range: "'" + tab + "'!A:F",
    channel,
    limit,
  };
}

export default ({ site, spreadsheet, tab, channel, limit }) => {
  const config = summarySettings(site, spreadsheet, tab, channel, limit);
  const listQuery = {
    status: "publish",
    orderby: "date",
    order: "desc",
    per_page: config.limit,
    page: 1,
    context: "view",
    _fields: "id,status,link",
  };
  return {
    config,
    spreadsheet: config.spreadsheet,
    range: config.range,
    listQuery,
    channel: config.channel,
  };
};

