function summaryHistory(rows) {
  if (!Array.isArray(rows) || !Array.isArray(rows[0]))
    throw new Error("The summary worksheet header is missing.");
  const headers = rows[0];
  const required = ["post_id", "summary", "post_link", "edit_link"];
  const dateHeaders = headers.filter((key) => ["summary_date", "summarized_date"].includes(key));
  const supported = [...required, "summary_date", "summarized_date", "title"];
  if (
    dateHeaders.length !== 1 ||
    new Set(headers).size !== headers.length ||
    !required.every((key) => headers.includes(key)) ||
    !headers.every((key) => supported.includes(key))
  ) {
    throw new Error(
      "The worksheet must contain the four required fields, one summary date field and optional title.",
    );
  }
  const idColumn = headers.indexOf("post_id");
  const ids = new Set();
  for (const row of rows.slice(1)) {
    if (!Array.isArray(row) || row.length > headers.length)
      throw new Error("A summary worksheet row is malformed.");
    if (row.every((value) => value === "" || value === null)) continue;
    const id = String(row[idColumn]);
    if (!/^[1-9]\d*$/.test(id) || !Number.isSafeInteger(Number(id)) || ids.has(id)) {
      throw new Error("Check the worksheet for blank, invalid or duplicate WordPress post IDs.");
    }
    ids.add(id);
  }
  return { headers, ids: [...ids] };
}

export default ({ rows }) => ({ sheet: summaryHistory(rows) });

