function postIds(posts, limit, origin) {
  if (!Array.isArray(posts) || posts.length > limit)
    throw new Error("WordPress did not return the requested post list.");
  const ids = posts.map((post) => {
    if (
      !Number.isSafeInteger(post?.id) ||
      post.id < 1 ||
      post.status !== "publish" ||
      typeof post.link !== "string" ||
      !post.link.startsWith(origin + "/")
    ) {
      throw new Error("WordPress returned an invalid ID or a post outside the published scope.");
    }
    return post.id;
  });
  if (new Set(ids).size !== ids.length) throw new Error("WordPress returned a duplicate post ID.");
  return ids;
}

export default ({ posts, status, config, sheet }) => {
  if (status !== 200) throw Error("WordPress did not confirm the list of recent posts.");
  return {
    ids: postIds(posts, config.limit, config.origin).filter(
      (id) => !sheet.ids.includes(String(id)),
    ),
  };
};

