export default async ({ ids, config, previous }, ctx) => {
  for (let index = (previous ?? -1) + 1; index < ids.length; index++) {
    const id = ids[index],
      key = "wordpress-summary:" + config.site + ":" + id;
    if (await ctx.state.get(key)) continue;
    return { index, more: true, id, key, endpoint: "/posts/" + id };
  }
  return { index: ids.length, more: false, id: 0, key: "", endpoint: "/posts" };
};

