function summaryBlock(response) {
  if (response?.status !== "completed" || !Array.isArray(response.output)) {
    throw new Error("OpenAI did not complete the summary.");
  }
  const messages = response.output.filter((item) => item.type === "message");
  const [message] = messages;
  if (
    messages.length !== 1 ||
    message.role !== "assistant" ||
    message.status !== "completed" ||
    message.content?.length !== 1 ||
    message.content[0]?.type !== "output_text"
  ) {
    throw new Error("OpenAI did not return a completed structured summary.");
  }
  const result = JSON.parse(message.content[0].text);
  const items = [result.point1, result.point2, result.point3, result.point4];
  const heading = result.heading;
  const valid = (text, limit) =>
    typeof text === "string" &&
    text.trim() &&
    text.length <= limit &&
    !/[\u0000-\u001f\u007f]/u.test(text);
  if (!valid(heading, 80) || items.some((item) => !valid(item, 350)))
    throw new Error("OpenAI returned invalid summary fields.");
  const escape = (text) =>
    text
      .trim()
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  return [
    "<!-- wp:html -->",
    '<div class="wp-block-group has-background wp-post-ai-summary" style="background-color:#f8faff;border-radius:4px;padding:10px;">',
    "<p><strong>✨ " + escape(heading) + "</strong></p>",
    "<ul>",
    ...items.map((item) => "<li>" + escape(item) + "</li>"),
    "</ul>",
    "</div>",
    "<!-- /wp:html -->",
    "",
    "<!-- wp:separator -->",
    '<hr class="wp-block-separator has-alpha-channel-opacity"/>',
    "<!-- /wp:separator -->",
  ].join("\n");
}

export default ({ reply }) => ({ block: summaryBlock(reply) });

