function sameRevision(before, fresh) {
  return (
    fresh.status === "publish" &&
    !fresh.protected &&
    before.id === fresh.id &&
    before.raw === fresh.raw &&
    before.modified === fresh.modified &&
    before.excerpt === fresh.excerpt &&
    before.title === fresh.title &&
    before.link === fresh.link
  );
}

function hasAiSummary(raw) {
  if (/\bwp-post-ai-summary\b/i.test(raw) || /<strong\b[^>]*>[^<]*\bAI\s+Summary\b/i.test(raw))
    return true;
  // The source’s translated block used a fixed blue background, radius and separator.
  const front = raw.trimStart().slice(0, 5000);
  return /^<!--\s*wp:html\s*-->[\s\S]*?<div\b[^>]*background-color\s*:\s*#f8faff\b[^>]*border-radius\s*:\s*4px[\s\S]*?<\/div>\s*<!--\s*\/wp:html\s*-->\s*<!--\s*wp:separator\b/i.test(
    front,
  );
}

export default async ({ response, status, config, id, before, block, key }, ctx) => {
  if (status !== 200)
    throw Error("WordPress failed the final article check. No edit was attempted.");
  const fresh = editablePost(response, id, config.origin);
  if (!sameRevision(before, fresh) || hasAiSummary(fresh.raw)) {
    return { write: false, body: {}, result: { postId: id, status: "changed_since_read" } };
  }
  const write = await ctx.state.insert(key, { postId: id, state: "wordpress_attempted" });
  return {
    write,
    body: { content: block + "\n\n" + before.raw },
    result: { postId: id, status: write ? "reserved" : "pending_or_already_done" },
  };
};

