    status: body.status,
    modified: body.modified_gmt,
    link: body.link,
    protected: body.content.protected === true || Boolean(body.password),
  };
}

function summarizeRow(updated, before, block, sheet, config, timestamp) {
  const expected = block + "\n\n" + before.raw;
  if (
    updated.raw !== expected ||
    updated.excerpt !== before.excerpt ||
    updated.status !== before.status ||
    updated.protected ||
    updated.title !== before.title ||
    updated.link !== before.link
  ) {
    throw new Error(
      "WordPress did not confirm the exact new block and preserved original article.",
    );
  }
  const id = String(updated.id);
  const date = timestamp || new Date().toISOString();
  const title = updated.title
    .replace(/<[^>]*>/g, "")
    .replace(/\s+/g, " ")
    .trim();
  const edit = config.site + "/wp-admin/post.php?post=" + id + "&action=edit";
  const row = {
    post_id: id,
    summary: block,
    post_link: updated.link,
    edit_link: edit,
    title,
    summary_date: date,
    summarized_date: date,
  };
  const word = title
    .replace(/[<>&*_`~|]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const text = [
    "WordPress post updated with an AI summary",
    word,
    "Post ID: " + id,
    "Article: <" + updated.link + ">",
    "Edit: <" + edit + ">",
  ]
    .filter(Boolean)
    .join("\n");
  return { id, values: sheet.headers.map((key) => row[key]), text };
}

export default async ({ response, status, config, id, before, block, key, sheet }, ctx) => {
  if (status !== 200)
    throw Error("WordPress did not confirm this edit. Inspect the post before retrying.");
  const row = summarizeRow(editablePost(response, id, config.origin), before, block, sheet, config);
  await ctx.state.set(key, { postId: id, state: "worksheet_attempted" });
  return { row, values: [row.values], text: row.text };
};

