function confirmSummaryLog(receipt, row, settings) {
  const { spreadsheetId, updatedRows, updatedRange, updatedData } = receipt ?? {};
  if (
    spreadsheetId !== settings.spreadsheet ||
    updatedRows !== 1 ||
    typeof updatedRange !== "string" ||
    !updatedRange.replace(/^'([^']+)'!/, "$1!").startsWith(settings.tab + "!") ||
    updatedData?.values?.length !== 1 ||
    JSON.stringify(updatedData.values[0]) !== JSON.stringify(row.values)
  ) {
    throw new Error(
      "Sheets did not confirm the exact post summary row. Before retrying, inspect the post and the worksheet.",
    );
  }
}

export default async ({ config, row, key, ...reply }, ctx) => {
  confirmSummaryLog(reply, row, config);
  await ctx.state.set(key, { postId: Number(row.id), state: "slack_attempted" });
  return {};
};

