export default async ({ channel, ts, config, key, id }, ctx) => {
  if (channel !== config.channel || !/^\d+\.\d+$/.test(ts))
    throw Error("Slack did not confirm the article notification.");
  const result = { postId: id, state: "completed", channel, ts };
  await ctx.state.set(key, result);
  return { result };
};
